// ── tests ───────────────────────────────────────────────────────────────

test('no grade → no receipt', () => {
    assert.equal(gradeReceiptPresentation({}, []), null);
    assert.equal(gradeReceiptPresentation({ grade: null }, []), null);
});

test('unadjusted receipt verifies and itemizes the base docks', () => {
    const r = gradeReceiptPresentation({ grade: gradeA }, [baseA]);
    assert.equal(r.verified, true);
    assert.equal(r.adjusted, false);
    assert.equal(r.base.found, true);
    assert.equal(r.base.score, 85);
    assert.equal(r.base.items.length, 3);
    const [i8, i14, i35] = r.base.items;
    assert.deepEqual(
        { item: i8.item, points: i8.points, cos: i8.cos, category: i8.category },
        { item: 8, points: 4.5, cos: true, category: 'risk_factor' });
    // repeat detected from the observation TEXT, not just the checklist flag
    assert.deepEqual({ item: i14.item, points: i14.points, repeat: i14.repeat },
        { item: 14, points: 9, repeat: true });
    assert.deepEqual({ item: i35.item, points: i35.points, category: i35.category },
        { item: 35, points: 2, category: 'grp' });
    assert.equal(r.followups.length, 0);
});

test('adjusted receipt derives every journey and reconciles', () => {
    const r = gradeReceiptPresentation({ grade: gradeB }, [fupB, baseB]);
    assert.equal(r.verified, true);
    assert.equal(r.adjusted, true);
    assert.equal(r.followups.length, 1);
    assert.equal(r.followups[0].kind, 'checklist');
    assert.equal(r.followups[0].label, '2/3 OUT');

    const restored = r.journeys.restored[0];
    assert.deepEqual(
        { item: restored.item, delta: restored.delta, dockPts: restored.dockPts },
        { item: 8, delta: 2.9, dockPts: 4.5 });   // 65% of the 4.5 COS'd dock
    const failed = r.journeys.failed[0];
    assert.deepEqual({ item: failed.item, delta: failed.delta },
        { item: 14, delta: 3 });                   // 9 charged − 6 base = 3 more
    const fresh = r.journeys.new[0];
    assert.deepEqual({ item: fresh.item, delta: fresh.delta, repeat: fresh.repeat },
        { item: 22, delta: 9, repeat: true });     // RF × 1.5 repeat flag
    assert.deepEqual(fresh.texts, ['Sanitizer bucket at 0 ppm, repeat noted']);
    const stands = r.journeys.unchecked[0];
    assert.deepEqual({ item: stands.item, dockPts: stands.dockPts },
        { item: 35, dockPts: 2 });

    // 88 + 2.9 − 12 = 78.9 ≠ 78: the round-once footnote must appear.
    assert.equal(r.ledger.exact, false);
    assert.deepEqual(
        { base: r.ledger.baseScore, restored: r.ledger.restored, added: r.ledger.added, score: r.ledger.score },
        { base: 88, restored: 2.9, added: 12, score: 78 });
});

test('narrative blanket clear restores at par and is flagged per item', () => {
    const r = gradeReceiptPresentation({ grade: gradeC }, [narrC, baseC]);
    assert.equal(r.verified, true);
    assert.equal(r.followups[0].kind, 'narrative');
    assert.equal(r.followups[0].label, 'All violations corrected');
    assert.equal(r.journeys.restored.length, 2);
    for (const row of r.journeys.restored) {
        assert.equal(row.narrative, true);
        assert.equal(row.delta, 3.9);              // 65% of a plain 6-point dock
    }
});

test('hybrid follow-up composes comment INs with checklist OUTs once', () => {
    const r = gradeReceiptPresentation({ grade: gradeD }, [hybridD, baseD]);
    assert.equal(r.verified, true);
    assert.equal(r.followups.length, 1);
    assert.equal(r.followups[0].kind, 'hybrid');
    assert.equal(r.followups[0].label, '3/5 OUT');
    assert.deepEqual(r.journeys.restored.map((i) => i.item), [1, 3]);
    assert.deepEqual(r.journeys.failed.map((i) => i.item), [22, 52, 55]);
});

test('reconcile mismatch degrades to bucket-level: no per-item points', () => {
    const tampered = { ...gradeC, restored_points: 9.9 };
    const r = gradeReceiptPresentation({ grade: tampered }, [narrC, baseC]);
    assert.equal(r.verified, false);
    // Membership (published) still renders; numbers do not.
    assert.equal(r.journeys.restored.length, 2);
    for (const row of r.journeys.restored) {
        assert.equal(row.delta, null);
        assert.equal(row.dockPts, null);
    }
    for (const it of r.base.items) assert.equal(it.points, null);
    // The published ledger is always safe to state.
    assert.equal(r.ledger.score, 96);
});

test('same-day visits gate on the Follow-Up purpose', () => {
    const routine = gradeReceiptPresentation({ grade: gradeE1 }, [sameDay('Routine'), baseE]);
    assert.equal(routine.verified, true);
    assert.equal(routine.adjusted, false);
    assert.equal(routine.followups.length, 0);

    const followup = gradeReceiptPresentation({ grade: gradeE2 }, [sameDay('Follow-Up'), baseE]);
    assert.equal(followup.verified, true);
    assert.equal(followup.adjusted, true);
    assert.deepEqual(
        { item: followup.journeys.restored[0].item, delta: followup.journeys.restored[0].delta },
        { item: 35, delta: 1.3 });
});

test('OUT+COS re-check revokes the base credit at full weight, no multiplier', () => {
    const r = gradeReceiptPresentation({ grade: gradeF }, [fupF, baseF]);
    assert.equal(r.verified, true);
    const row = r.journeys.cos[0];
    // 6 full − 4.5 discounted = 1.5 revoked; base item shows its COS chip data
    assert.deepEqual({ item: row.item, delta: row.delta, cosBase: row.cosBase },
        { item: 8, delta: 1.5, cosBase: true });
    assert.equal(r.ledger.added, 1.5);
});

test('missing base row degrades but keeps published totals', () => {
    const r = gradeReceiptPresentation({ grade: gradeB }, [fupB]);  // base row absent
    assert.equal(r.verified, false);
    assert.equal(r.base.found, false);
    assert.equal(r.base.score, 88);
    assert.equal(r.ledger.score, 78);
    // Journeys still list the published membership, numberless.
    assert.equal(r.journeys.restored.length, 1);
    assert.equal(r.journeys.restored[0].delta, null);
});

test('the base docket is one row per violation, each with its own charge', () => {
    const r = gradeReceiptPresentation({ grade: gradeG }, [fupG, baseG]);
    assert.equal(r.verified, true);

    // Five findings under two item numbers -> five rows, not two. Sharing an
    // item is read off the repeated item number and row adjacency, not a
    // dedicated field — sorted by item, filed in document order.
    assert.equal(r.base.items.length, 5);
    assert.deepEqual(r.base.items.map((i) => i.item), [8, 8, 47, 47, 47]);
    // Each carries its own text and its own points.
    const [a, b] = r.base.items;
    assert.equal(a.points, 6);
    assert.equal(b.text, 'Cut melon held at 51F in the prep-table insert');
    assert.equal(r.base.items[4].text, 'Standing water under the ice machine');
    // Item 47's three findings are 2 points each, not one 6-point row.
    assert.deepEqual(r.base.items.slice(2).map((i) => i.points), [2, 2, 2]);

    // Journeys are per FINDING too, symmetric with the docket: a re-check
    // resolves the findings it re-cites by code, so one item can hold a
    // re-cited finding beside an un-recited one. Each row states one finding.
    assert.equal(r.journeys.restored.length, 2);
    assert.deepEqual(r.journeys.restored.map((x) => x.item), [8, 8]);
    assert.deepEqual(r.journeys.restored.map((x) => x.texts.length), [1, 1]);
    assert.equal(r.journeys.unchecked.length, 3);
    assert.deepEqual(r.journeys.unchecked.map((x) => x.item), [47, 47, 47]);
});

test('a journey row states one finding\'s badges, never an item-wide claim', () => {
    const r = gradeReceiptPresentation({ grade: gradeI }, [fupI, baseH]);
    assert.equal(r.verified, true);

    // Item 47 was never re-checked, so both its findings carry — as two rows,
    // because only one was a repeat and only one was fixed on site. An
    // aggregate row could state one of those and would be silent on the other.
    const rows = r.journeys.unchecked;
    assert.equal(rows.length, 2);
    assert.deepEqual(rows.map((x) => x.item), [47, 47]);
    assert.deepEqual(rows.map((x) => x.repeat), [true, false]);
    assert.deepEqual(rows.map((x) => x.cosBase), [true, false]);
    // 2×1.5×0.75 = 2.25 (shown to 1dp) beside a plain 2 — together the 4.25
    // the item carries, but now attributable.
    assert.deepEqual(rows.map((x) => x.dockPts), [2.3, 2]);
    assert.deepEqual(rows.map((x) => x.texts.length), [1, 1]);
});

test('split badges charge each finding on its own, not the item', () => {
    const r = gradeReceiptPresentation({ grade: gradeH }, [baseH]);
    assert.equal(r.verified, true);

    // Item 47: row 1 badged COS+Repeat, row 2 plain. 2x1.5x0.75 + 2 = 4.25,
    // where the old item-level merge spread the repeat and killed the credit
    // for a flat 6.
    const rows = r.base.items.filter((i) => i.item === 47);
    assert.equal(rows.length, 2);
    assert.deepEqual({ points: rows[0].points, repeat: rows[0].repeat, cos: rows[0].cos },
        { points: 2.3, repeat: true, cos: true });      // 2.25, shown to 1dp
    assert.deepEqual({ points: rows[1].points, repeat: rows[1].repeat, cos: rows[1].cos },
        { points: 2, repeat: false, cos: false });
    // The neighbouring plain risk factor is untouched by either badge.
    const rf = r.base.items.find((i) => i.item === 8);
    assert.deepEqual({ points: rf.points, repeat: rf.repeat, cos: rf.cos },
        { points: 6, repeat: false, cos: false });
});

test('a new item docks once no matter how many findings the re-check wrote', () => {
    const r = gradeReceiptPresentation({ grade: gradeG }, [fupG, baseG]);
    const fresh = r.journeys.new[0];
    assert.deepEqual({ item: fresh.item, count: fresh.count, n: fresh.texts.length },
        { item: 61, count: 2, n: 2 });
    assert.equal(fresh.delta, 2);          // ONE retail-practice weight, not two
    // …so the chip must not claim the weights summed.
    assert.equal(fresh.countSums, false);
});

// ── wiring tripwires (source + CSS stay in step) ────────────────────────

test('the hero circle AND the computed pill both trigger the receipt', () => {
    // Anchor on the method DEFINITIONS (the call sites appear earlier).
    const heroStart = source.indexOf("_gradeHero(g, sparkHtml = '', interactive = true)");
    assert.ok(heroStart !== -1, '_gradeHero definition found');
    const hero = source.slice(heroStart,
        source.indexOf('_newHero(latestView)', heroStart));
    const triggers = hero.match(/data-grade-receipt/g) || [];
    assert.equal(triggers.length, 2, 'circle + pill each carry data-grade-receipt');
    assert.match(hero, /aria-haspopup="dialog"/);
});

test('the full detail render binds the receipt openers', () => {
    assert.match(source, /this\._bindGradeReceipt\(inner, detail\.facility, detail\.inspections\)/);
    // Facility switches and panel closes must not strand an open modal.
    assert.match(source, /_closeDetail\(\)\s*\{\s*this\._closeReceipt\(\)/);
});

test('the item row prints every finding, never just the first', () => {
    // Anchor on the name, not the parameter list — this test is about what the
    // row renders, and pinning the signature makes it fail on every unrelated
    // argument added to itemRow.
    const start = source.indexOf('const itemRow = (');
    assert.ok(start !== -1, 'itemRow definition found');
    const row = source.slice(start, source.indexOf('── section 1', start));
    assert.match(row, /texts\.map\(/, 'itemRow renders the whole texts list');
    assert.ok(!/it\.text\b/.test(row), 'no single-text fallback survives');
    assert.ok(css.includes('.food-receipt-item-texts'),
        'style.css ships the multi-finding list');
});

// Case K — one item, two findings; the follow-up re-cites ONE of them by its
// regulatory code. The engine joins the verdict to that finding and leaves its
// neighbour unchecked, so item 55 belongs to two buckets at once.
const baseK = {
    inspection_id: 'K1', date: '2026-05-19', scope: 'broad', score: 96,
    checklist: [
        { item: 55, disposition: 'OUT', violation: true },
        { item: 55, disposition: 'OUT', violation: true },
    ],
    violations: [
        { item: 55, code: '12VAC5-421-3180.A',
            text: 'Heavy grease buildup on floors under the cook line' },
        { item: 55, code: '12VAC5-421-3170',
            text: 'Floor tiles cracked and grout worn through the kitchen' },
    ],
};
const fupK = {
    inspection_id: 'K2', date: '2026-06-15', scope: 'focused',
    purpose: 'Follow-Up',
    checklist: [{ item: 55, disposition: 'OUT', violation: true }],
    violations: [
        { item: 55, code: '12VAC5-421-3170',
            text: 'Floor tiles cracked and grout worn through the kitchen' },
    ],
};
const gradeK = {
    score: 95, letter: 'A', base_score: 96, base_letter: 'A',
    base_date: '2026-05-19', base_inspection_id: 'K1', adjusted: true,
    followups: 1, followup_date: '2026-06-15', narrative_followups: 0,
    narrative_items: [], restored_items: [], failed_items: [55],
    cos_items: [], new_items: [], unchecked_items: [55],
    restored_findings: [], failed_findings: [1], cos_findings: [],
    unchecked_findings: [0],
    restored_points: 0.0, extra_points: 1.0,
};

test('a re-cited finding fails while its neighbour goes unchecked', () => {
    const r = gradeReceiptPresentation({ grade: gradeK }, [fupK, baseK]);
    assert.equal(r.verified, true, 'per-finding membership reconciles');

    // One item, two fates. Item-level resolution could express only one.
    const [failed] = r.journeys.failed;
    const [carried] = r.journeys.unchecked;
    assert.equal(failed.item, 55);
    assert.equal(carried.item, 55);
    assert.match(failed.texts[0], /Floor tiles cracked/);
    assert.match(carried.texts[0], /Heavy grease buildup/);

    // The re-cited finding revokes to full ×1.5 (2 → 3, so +1); the spared one
    // carries its face value and adds nothing.
    assert.equal(failed.delta, 1);
    assert.equal(carried.dockPts, 2);
    assert.equal(carried.delta, null);
    assert.equal(r.ledger.added, 1);
});

test('legacy payloads without *_findings still expand to per-finding rows', () => {
    // Published before per-finding resolution: every finding under an item
    // shared one fate, so expanding the item's dock reproduces what it meant.
    const legacy = { ...gradeK, unchecked_items: [], failed_items: [55] };
    delete legacy.failed_findings;
    delete legacy.unchecked_findings;
    delete legacy.restored_findings;
    delete legacy.cos_findings;
    const r = gradeReceiptPresentation({ grade: legacy }, [fupK, baseK]);
    assert.equal(r.journeys.failed.length, 2, 'both findings under item 55');
    assert.deepEqual(r.journeys.failed.map((x) => x.item), [55, 55]);
});

