    assert.deepEqual(r.journeys.failed.map((x) => x.item), [22, 55]);
    assert.match(r.journeys.failed[1].texts[0], /Floor tiles cracked/);
    assert.equal(r.journeys.unchecked.length, 0, 'every finding got a word');
